// Cleanup worker. Until 12 November 2026 this site ran on a Jekyll theme that
// registered /sw.min.js and kept every page for offline use. That worker
// answers from its own cache and never asks the network again, so browsers
// that visited back then kept showing the old homepage.
//
// Browsers re-check this address on every visit. When they find this file
// they swap it in, and it deletes the old cache, unregisters itself and
// reloads the open tabs from the network.
//
// Keep this file. Without it, a browser that has not come back yet stays
// stuck on the old site.
self.addEventListener('install', () => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const tabs = await self.clients.matchAll({ type: 'window' });
      await Promise.all(tabs.map((tab) => tab.navigate(tab.url).catch(() => null)));
    })(),
  );
});
